// Firmware for the ESP32 sensor development board: reads a BME280 over I2C and serves the readings as JSON on Wi-Fi.
// Wi-Fi credentials are entered over the serial console on first boot (or after holding USER for 3 s at start-up)
// and stored in NVS with the Preferences library, so no credential is ever part of the source code.
#include <Arduino.h>
#include <Wire.h>
#include <WiFi.h>
#include <WebServer.h>
#include <Preferences.h>
#include <Adafruit_BME280.h>
#include "pins.h"
#include "config.h"

static Adafruit_BME280 bme;
static WebServer server(HTTP_PORT);
static Preferences prefs;
static bool sensorReady = false;
static float temperatureC = NAN, humidityPct = NAN, pressureHpa = NAN;
static unsigned long lastRead = 0;

// Read one line from the serial console, echoing characters, until Enter.
static String readLine(const char *prompt) {
  Serial.print(prompt);
  String line;
  while (true) {
    while (!Serial.available()) delay(10);
    char c = Serial.read();
    if (c == '\r' || c == '\n') { if (line.length()) break; else continue; }
    line += c;
    Serial.print(c);
  }
  Serial.println();
  return line;
}

// Ask for Wi-Fi credentials and keep them in NVS.
static void provisionWifi() {
  Serial.println("Wi-Fi setup: enter the network name and passphrase.");
  String ssid = readLine("SSID: ");
  String pass = readLine("Passphrase: ");
  prefs.putString("ssid", ssid);
  prefs.putString("pass", pass);
}

static bool connectWifi() {
  String ssid = prefs.getString("ssid", "");
  if (!ssid.length()) return false;
  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid.c_str(), prefs.getString("pass", "").c_str());
  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < WIFI_CONNECT_TIMEOUT_MS) {
    digitalWrite(PIN_LED_STATUS, !digitalRead(PIN_LED_STATUS));  // Blink while connecting
    delay(250);
  }
  digitalWrite(PIN_LED_STATUS, WiFi.status() == WL_CONNECTED ? HIGH : LOW);
  return WiFi.status() == WL_CONNECTED;
}

static float vbusVolts() {
  return analogReadMilliVolts(PIN_VBUS_SENSE) / 1000.0f * VBUS_DIVIDER_RATIO;
}

static void handleReadings() {
  String json = "{";
  json += "\"temperature_c\":" + String(temperatureC, 2) + ",";
  json += "\"humidity_pct\":" + String(humidityPct, 1) + ",";
  json += "\"pressure_hpa\":" + String(pressureHpa, 1) + ",";
  json += "\"vbus_v\":" + String(vbusVolts(), 2) + ",";
  json += "\"sensor_ok\":" + String(sensorReady ? "true" : "false");
  json += "}";
  server.send(200, "application/json", json);
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN_LED_STATUS, OUTPUT);
  pinMode(PIN_USER_BUTTON, INPUT_PULLUP);
  analogSetPinAttenuation(PIN_VBUS_SENSE, ADC_11db);
  prefs.begin("board", false);

  Wire.begin(PIN_I2C_SDA, PIN_I2C_SCL);
  sensorReady = bme.begin(BME280_I2C_ADDRESS, &Wire);
  if (!sensorReady) Serial.println("BME280 not found: check the sensor and the I2C pull-ups.");

  bool forceSetup = digitalRead(PIN_USER_BUTTON) == LOW;  // Hold USER at power-up to re-enter Wi-Fi setup
  if (forceSetup || !prefs.getString("ssid", "").length()) provisionWifi();
  if (connectWifi()) {
    Serial.print("Readings at http://");
    Serial.print(WiFi.localIP());
    Serial.println("/readings");
  } else {
    Serial.println("Wi-Fi not connected; readings stay on the serial console.");
  }
  server.on("/readings", handleReadings);
  server.begin();
}

void loop() {
  server.handleClient();
  if (millis() - lastRead >= SENSOR_PERIOD_MS) {
    lastRead = millis();
    if (sensorReady) {
      temperatureC = bme.readTemperature();
      humidityPct = bme.readHumidity();
      pressureHpa = bme.readPressure() / 100.0f;
      Serial.printf("T=%.2f C  RH=%.1f %%  P=%.1f hPa  VBUS=%.2f V\n", temperatureC, humidityPct, pressureHpa, vbusVolts());
    }
  }
}
